resolved as (
    select
        HUB_POLICY_HK,
        coalesce(max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PREVIOUS_INSURER_NAME end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then PREVIOUS_INSURER_NAME end)) as PREVIOUS_INSURER_NAME,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PREVIOUS_SUM_INSURED end) as PREVIOUS_SUM_INSURED,
        coalesce(max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PREVIOUS_POLICY_NUMBER end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then PREVIOUS_POLICY_NUMBER end)) as PREVIOUS_POLICY_NUMBER,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CUMULATIVE_BONUS_PORTED end) as CUMULATIVE_BONUS_PORTED,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PORTABILITY_INDICATOR end) as PORTABILITY_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CONTINUITY_PERIOD_GRANTED end) as CONTINUITY_PERIOD_GRANTED,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_POLICY_HK
),

hashed as (
    select
        *,
        case when PREVIOUS_INSURER_NAME is not null or PREVIOUS_SUM_INSURED is not null or PREVIOUS_POLICY_NUMBER is not null or CUMULATIVE_BONUS_PORTED is not null or PORTABILITY_INDICATOR is not null or CONTINUITY_PERIOD_GRANTED is not null
                     then md5(upper(coalesce(cast(PREVIOUS_INSURER_NAME as varchar), '') || '|' || coalesce(cast(PREVIOUS_SUM_INSURED as varchar), '') || '|' || coalesce(cast(PREVIOUS_POLICY_NUMBER as varchar), '') || '|' || coalesce(cast(CUMULATIVE_BONUS_PORTED as varchar), '') || '|' || coalesce(cast(PORTABILITY_INDICATOR as varchar), '') || '|' || coalesce(cast(CONTINUITY_PERIOD_GRANTED as varchar), '')))
                end as SAT_POLICY_PORTABILITY_MIGRATION_HASHDIFF
    from resolved
)

select * from hashed
where HUB_POLICY_HK is not null
  and SAT_POLICY_PORTABILITY_MIGRATION_HASHDIFF is not null
